<script setup lang="ts">import {ref} from 'vue';import {ArrowRight,X,Plus} from 'lucide-vue-next';import PageHeader from '../components/PageHeader.vue';import StatusBadge from '../components/StatusBadge.vue';import {maintenance,type MaintenanceItem} from '../data/mock';import {useVintro} from '../composables/useVintro';const {notify}=useVintro();const selected=ref<MaintenanceItem|null>(null);const adding=ref(false);const reminder=ref({name:'Vehicle inspection',basis:'Date',date:'2027-03-01',kilometres:100000});const saveReminder=()=>{adding.value=false;notify('Reminder added for '+reminder.value.name)}

</script>
<template><PageHeader title="Upcoming maintenance" back="/vehicle/bmw-320d"><button @click="adding=true" class="btn-secondary !min-h-10"><Plus :size="16"/>Reminder</button></PageHeader><div class="container-app max-w-4xl py-7"><p class="eyebrow">BMW 320d Touring</p><h1 class="page-title mt-2">What comes next</h1><p class="mt-3 text-muted">Manufacturer guidance, workshop recommendations and reminders you choose to set.</p><section class="mt-9"><h2 class="section-title text-red-700">Overdue</h2><div class="mt-3 space-y-3"><button v-for="m in maintenance.filter(x=>x.status==='Overdue')" @click="selected=m" class="card w-full border-red-200 p-5 text-left"><StatusBadge :status="m.status"/><h3 class="mt-3 text-lg font-semibold">{{m.name}}</h3><div class="mt-4 flex justify-between border-t pt-4 text-sm"><span class="text-muted">Was due</span><strong>{{m.dueDate}}</strong></div></button></div></section><section class="mt-9"><h2 class="section-title">Due soon &amp; recommended</h2><div class="mt-3 space-y-3"><button v-for="m in maintenance.filter(x=>x.status==='Due soon')" @click="selected=m" class="card w-full p-5 text-left hover:shadow-soft"><div class="flex items-start justify-between"><div><StatusBadge :status="m.status"/><h3 class="mt-3 text-lg font-semibold">{{m.name}}</h3></div><ArrowRight :size="18" class="text-muted"/></div><div v-if="m.remaining" class="mt-5"><div class="flex justify-between text-xs"><span class="nums">Current 87,420 km</span><span class="nums font-semibold">{{m.remaining.toLocaleString()}} km left</span></div><div class="mt-2 h-1.5 rounded-full bg-stone-200"><div class="h-full w-[83%] rounded-full bg-amber"/></div></div><div class="mt-4 flex justify-between border-t pt-4 text-sm"><span class="text-muted">Estimated due</span><strong>{{m.dueDate}}</strong></div></button></div></section><section class="mt-9"><h2 class="section-title">Later</h2><div class="mt-3 divide-y rounded-2xl border bg-white"><button v-for="m in maintenance.filter(x=>x.status==='Up to date')" @click="selected=m" class="flex w-full items-center justify-between p-5 text-left hover:bg-stone-50"><div><h3 class="font-semibold">{{m.name}}</h3><p class="nums mt-1 text-sm text-muted">{{m.dueAt?.toLocaleString()}} km · {{m.remaining?.toLocaleString()}} km remaining</p></div><ArrowRight :size="18" class="text-muted"/></button></div></section><button @click="adding=true" class="mt-6 flex w-full items-center justify-center gap-2 rounded-2xl border border-dashed py-5 text-sm font-semibold text-accent hover:bg-white"><Plus :size="18"/>Set your own reminder</button></div><Teleport to="body"><div v-if="selected" class="fixed inset-0 z-[80] flex items-end bg-black/30 backdrop-blur-sm" @click.self="selected=null"><div class="mx-auto w-full max-w-xl rounded-t-3xl bg-white p-6 pb-10 shadow-soft"><div class="flex items-start justify-between"><div><StatusBadge :status="selected.status"/><h2 class="mt-3 text-2xl font-semibold">{{selected.name}}</h2></div><button @click="selected=null" class="grid h-10 w-10 place-items-center rounded-full bg-stone-100"><X :size="18"/></button></div><p class="mt-5 leading-7 text-muted">{{selected.why}}</p><dl class="mt-6 divide-y rounded-xl border px-4"><div class="flex justify-between py-4 text-sm"><dt class="text-muted">Last completed</dt><dd class="font-semibold">{{selected.last}}</dd></div><div class="flex justify-between py-4 text-sm"><dt class="text-muted">Recommended interval</dt><dd class="text-right font-semibold">{{selected.interval}}</dd></div><div class="flex justify-between py-4 text-sm"><dt class="text-muted">Estimated due</dt><dd class="font-semibold">{{selected.dueDate}}</dd></div></dl></div></div><div v-if="adding" class="fixed inset-0 z-[80] flex items-end bg-black/30 backdrop-blur-sm" @click.self="adding=false"><form @submit.prevent="saveReminder" class="mx-auto w-full max-w-xl rounded-t-3xl bg-white p-6 pb-10 shadow-soft"><div class="flex items-center justify-between"><h2 class="text-2xl font-semibold">Set reminder</h2><button type="button" @click="adding=false" class="grid h-10 w-10 place-items-center rounded-full bg-stone-100"><X :size="18"/></button></div><p class="mt-2 text-sm text-muted">Choose a date, mileage, or use both.</p><label class="mt-6 block"><span class="label">Reminder</span><input v-model="reminder.name" class="field" required/></label><label class="mt-4 block"><span class="label">Remind by</span><select v-model="reminder.basis" class="field"><option>Date</option><option>Mileage</option><option>Date and mileage</option></select></label><div class="mt-4 grid grid-cols-2 gap-3"><label><span class="label">Date</span><input v-model="reminder.date" type="date" class="field nums"/></label><label><span class="label">Mileage</span><input v-model="reminder.kilometres" type="number" class="field nums"/></label></div><button class="btn-primary mt-6 w-full">Save reminder</button></form></div></Teleport></template>
